# SPDX-License-Identifier: AGPL-3.0-only
from fractions import Fraction

def solve(payload):
    current = Fraction(*payload['initial'])
    for index, operation in enumerate(payload['operations']):
        right = Fraction(*operation['value'])
        action = operation['op']
        if action == 'add':
            current = Fraction(current.numerator + right.numerator, current.denominator + right.denominator)
        elif action == 'subtract':
            current = current - right
        elif action == 'multiply':
            current *= right
        else:
            if right == 0:
                return {'error': 'division_by_zero', 'index': index}
            current /= right
    return {'value': [current.numerator, current.denominator]}

